//! The local socket identity sent to peers.

use std::fmt;

use crate::Frame;

/// The identity this socket announces to its peers (ZMTP `Identity`).
///
/// At most 255 octets. A non-empty identity must not start with `0x00`,
/// which RFC 37 reserves for identities generated by the receiving peer.
#[derive(Debug, Clone, Default, PartialEq, Eq, Hash)]
pub struct Identity(Frame);

/// Why an [`Identity`] was rejected.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InvalidIdentity {
    /// Longer than 255 octets.
    TooLong,
    /// Starts with the reserved `0x00` octet.
    ReservedPrefix,
}

impl Identity {
    /// Validates `identity`.
    pub fn new(identity: impl Into<Frame>) -> Result<Self, InvalidIdentity> {
        let identity = identity.into();
        if identity.len() > usize::from(u8::MAX) {
            Err(InvalidIdentity::TooLong)
        } else if identity.first() == Some(&0) {
            Err(InvalidIdentity::ReservedPrefix)
        } else {
            Ok(Self(identity))
        }
    }

    /// The identity octets.
    pub fn as_slice(&self) -> &[u8] {
        &self.0
    }
}

impl fmt::Display for InvalidIdentity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::TooLong => "identity is longer than 255 octets",
            Self::ReservedPrefix => "identity must not start with 0x00",
        })
    }
}

impl std::error::Error for InvalidIdentity {}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_identity_is_valid() {
        assert_eq!(Identity::default().as_slice(), b"");
        assert_eq!(Identity::new(Frame::new()).unwrap().as_slice(), b"");
    }

    #[test]
    fn up_to_255_octets_is_valid() {
        let id = Identity::new(vec![b'a'; 255]).unwrap();
        assert_eq!(id.as_slice().len(), 255);
    }

    #[test]
    fn longer_than_255_octets_is_rejected() {
        assert_eq!(
            Identity::new(vec![b'a'; 256]),
            Err(InvalidIdentity::TooLong)
        );
    }

    #[test]
    fn leading_zero_octet_is_rejected() {
        assert_eq!(
            Identity::new(&b"\x00abc"[..]),
            Err(InvalidIdentity::ReservedPrefix)
        );
        assert_eq!(
            InvalidIdentity::ReservedPrefix.to_string(),
            "identity must not start with 0x00"
        );
        assert_eq!(
            InvalidIdentity::TooLong.to_string(),
            "identity is longer than 255 octets"
        );
    }
}
